def even_odd_palindrome(n):
    if n < 2:
        return (1, 0)

    evens = 0
    odds = 0
    for i in range(1, n + 1):
        num = str(i)
        if num[0] == num[-1]:
            if i % 2 == 0:
                evens += 2
            else:
                odds += 2
        if i < n:
            continue
        if i != int_palindrome(num):
            continue
    return (evens, odds)

def int_palindrome(num):
    return int(num) == str(num)

```

