def string_sequence(n: int) -> str:
    """ Return a string containing space-delimited numbers from 0 upto n inclusive.
    >>> string_sequence(0)
    '0'
    >>> string_sequence(5)
    '0 1 2 3 4 5'
    """

    def generate_numbers(start, end):
        """ Generate a list of numbers from start to end."""
        return [i for i in range(start, end + 1)]

    def format_string(numbers):
        """ Format a string with space-delimited numbers. """
        return ' '.join(map(str, numbers))

    if n == 0:
        return "0"
    elif n > 0:
        return format_string(generate_numbers(0, n))
```

